    "integratedServices": [],
    "faqs": [
      {
        "q": "Can you help me start selling on Flipkart?",
        "a": "Yes. We can assist with seller onboarding guidance, documentation preparation, account configuration and catalogue readiness. Account approval and seller eligibility depend on Flipkart's current requirements and verification procedures."
      },
      {
        "q": "I already have a Flipkart seller account. Can you manage it?",
        "a": "Yes. We can review your existing account and discuss catalogue management, listing optimisation, advertising, account health and operational support based on your requirements."
      },
      {
        "q": "Do you provide Flipkart Ads management?",
        "a": "Yes. We can discuss advertising campaign setup, budget monitoring, performance analysis and optimisation, depending on the features available to your account and the agreed scope."
      },
      {
        "q": "Do you guarantee sales or a specific ROAS?",
        "a": "No. Sales, product visibility and advertising returns depend on demand, competition, pricing, product quality, customer feedback, inventory, advertising budget and other factors. Our focus is on structured management and continuous improvement."
      },
      {
        "q": "Do I need GST to sell on Flipkart India?",
        "a": "GST requirements depend on the product category, applicable law and current marketplace rules. Certain eligible sellers or categories may qualify for specific exceptions. We can provide general guidance, but tax and legal decisions should be confirmed with a qualified professional."
      },
      {
        "q": "Can you create product listings for my business?",
        "a": "Yes. Depending on the agreed scope, we can assist with catalogue uploads, product titles, descriptions, specifications, attributes, variations and listing corrections."
      },
      {
        "q": "Do you provide product photography and graphic design?",
        "a": "We can support product image planning, infographics, visual content coordination and related creative services. Photography and additional production work can be scoped separately or included in an agreed package."
      },
      {
        "q": "Can you help with inactive or suppressed listings?",
        "a": "We can review available listing information, identify potential catalogue issues and coordinate corrective actions. Final listing activation depends on the underlying issue and Flipkart's policies and decisions."
      },
      {
        "q": "Can you manage inventory and orders?",
        "a": "We can assist with inventory monitoring, order and fulfilment status tracking, operational reporting and issue coordination. Physical warehousing, packing and logistics depend on the applicable fulfilment arrangement and separately agreed responsibilities."
      },
      {
        "q": "How much do your Flipkart management services cost?",
        "a": "Our fees depend on catalogue size, account condition, advertising requirements and the level of ongoing support needed. Request a consultation to receive a customised scope and quotation."
      },
      {
        "q": "How long does it take to see results?",
        "a": "The timeline varies according to account readiness, product category, listing quality, pricing, competition, inventory and advertising activity. We identify priorities based on your situation but do not promise a fixed results timeline."
      },
      {
        "q": "Can I choose only catalogue management without advertising?",
        "a": "Service availability depends on your requirements and the agreed scope. We can discuss catalogue-only support, advertising-only assistance or a broader management engagement during the consultation."
      }
    ],
