    "faqs": [
      {
        "q": "What is FirstCry Management?",
        "a": "FirstCry Management is support for agreed seller onboarding preparation, product catalogue organisation, listing content, operational coordination, and reporting, depending on seller eligibility, account access, and available platform functions."
      },
      {
        "q": "Can E-COMET OUTVERSE help me become a FirstCry seller?",
        "a": "We can discuss the applicable onboarding process and help organise relevant business and product information. Registration availability, eligibility, and final account approval must be confirmed against FirstCry's current requirements."
      },
      {
        "q": "Do I need an existing FirstCry seller account?",
        "a": "Not necessarily for an initial consultation. We can discuss your business and determine whether onboarding preparation or support for an existing account is appropriate. Actual delivery depends on eligibility, available onboarding routes, and account permissions."
      },
      {
        "q": "Which products can be managed?",
        "a": "We can discuss eligible baby, kids, nursery, toy, clothing, accessory, and related product categories. Final scope depends on FirstCry's current category acceptance and seller requirements."
      },
      {
        "q": "Can you manage product sizes, colours, and variations?",
        "a": "We can organise product information and coordinate supported variations using seller-approved data. Actual variation structures depend on the platform's catalogue rules and available account functions."
      },
      {
        "q": "Can you write product descriptions and optimise listings?",
        "a": "Yes. We can prepare and maintain agreed listing content using accurate, seller-approved product information. Listing submission and editing depend on account permissions and marketplace requirements."
      },
      {
        "q": "Can you create product images and infographics?",
        "a": "Product photography, image editing, infographics, and other creative deliverables can be discussed as separate or integrated services. The number and type of deliverables will be specified in the quotation."
      },
      {
        "q": "How do you handle product safety information?",
        "a": "We use accurate, seller-provided or seller-approved information. We do not invent safety certifications, age recommendations, medical claims, ingredients, or product benefits. The seller remains responsible for the accuracy and supporting documentation of product claims."
      },
      {
        "q": "Do you handle inventory, orders, and delivery?",
        "a": "We can support agreed inventory tracking and order-related monitoring where information and account functions are available. Physical stock handling, packing, dispatch, delivery, and fulfilment are not included unless separately agreed."
      },
      {
        "q": "Can you guarantee sales or better rankings?",
        "a": "No. Sales and rankings depend on product demand, competition, pricing, availability, customer preferences, marketplace decisions, and other factors. We focus on delivering the agreed management activities and operational support."
      },
      {
        "q": "How much does FirstCry Management cost?",
        "a": "We do not display fixed prices on the website. The quotation depends on catalogue size, account status, product complexity, required services, and update frequency. Request a consultation for a customised proposal."
      },
      {
        "q": "Can I combine FirstCry Management with other E-COMET OUTVERSE services?",
        "a": "Yes. Depending on your business requirements, you can discuss combining marketplace management with website development, digital marketing, creative design, photography, or video production."
      },
      {
        "q": "How long does onboarding take?",
        "a": "Timelines depend on seller eligibility, document readiness, product information, account access, and marketplace processes. We will clarify the expected work stages after reviewing your requirements, but platform approval timelines cannot be guaranteed."
      },
      {
        "q": "What should I prepare before the consultation?",
        "a": "Prepare your business details, product categories, approximate SKU count, current seller account status, available product information, and operational requirements. Do not submit passwords, OTPs, banking credentials, or other sensitive account access information through the enquiry form."
      }
    ],
