    "faqs": [
      {
        "q": "What is Shopsy Management?",
        "a": "Shopsy Management is support for agreed seller onboarding preparation, product catalogue organisation, listing content, operational coordination, and reporting, depending on seller eligibility, account access, and available platform functions."
      },
      {
        "q": "Can E-COMET OUTVERSE help me become a Shopsy seller?",
        "a": "We can discuss the applicable seller onboarding process and help organise relevant business and product information. Registration availability, eligibility, and final approval must be confirmed against the platform's current requirements."
      },
      {
        "q": "Do I need an existing seller account?",
        "a": "Not necessarily for an initial consultation. We can first discuss your business and determine whether onboarding preparation or support for an existing account is appropriate. Actual delivery depends on eligibility, available onboarding routes, and account permissions."
      },
      {
        "q": "Which products can be managed?",
        "a": "We can discuss eligible product categories based on your business and the platform's current seller and category requirements. The final scope will be confirmed after reviewing your product range."
      },
      {
        "q": "Can you create and optimise product listings?",
        "a": "We can prepare product content and support agreed catalogue activities. Actual listing submission and editing depend on account permissions, available platform functions, category requirements, and marketplace approval."
      },
      {
        "q": "Can you manage product variations?",
        "a": "We can organise seller-provided product attributes and coordinate supported variations where permitted. Actual variation structures depend on the applicable catalogue rules and account capabilities."
      },
      {
        "q": "Do you manage pricing and inventory?",
        "a": "We can organise pricing and inventory information and coordinate approved updates where supported. Final commercial decisions and stock accuracy remain the seller's responsibility."
      },
      {
        "q": "Do you handle packing and delivery?",
        "a": "We may provide agreed order-related monitoring and operational coordination where information is available. Physical stock handling, packing, dispatch, delivery, and fulfilment are not included unless separately agreed in writing."
      },
      {
        "q": "Can you guarantee sales or higher rankings?",
        "a": "No. Sales and rankings depend on product demand, competition, pricing, availability, customer preferences, marketplace decisions, and other factors. Our focus is on delivering agreed management activities and operational support."
      },
      {
        "q": "How much does Shopsy Management cost?",
        "a": "We do not display fixed prices on the website. The quotation depends on catalogue size, account status, required services, update frequency, and operational complexity. Request a consultation for a customised proposal."
      },
      {
        "q": "Can I combine Shopsy Management with other services?",
        "a": "Yes. Depending on your business requirements, you can discuss combining marketplace management with website development, digital marketing, creative design, photography, or video production."
      },
      {
        "q": "How long does onboarding take?",
        "a": "Timelines depend on seller eligibility, document readiness, product information, account access, and platform processes. We will discuss the expected work stages after reviewing your requirements, but approval timelines cannot be guaranteed."
      },
      {
        "q": "What information should I prepare before the consultation?",
        "a": "Prepare your business details, product categories, approximate catalogue size, current account status, available product information, and operational requirements. Do not submit passwords, OTPs, banking credentials, or other sensitive account access information through the enquiry form."
      }
    ],
