    "faqs": [
      {
        "q": "What is Amazon Global Management?",
        "a": "Amazon Global Management is support for businesses that want to evaluate, establish, or manage selling activities across eligible Amazon international marketplaces. It can include marketplace planning, account preparation, catalogue management, listing optimisation, advertising, operational coordination, and reporting."
      },
      {
        "q": "Can an Indian business sell on Amazon internationally?",
        "a": "Some Indian businesses may be eligible to sell internationally, but eligibility depends on the seller, products, destination marketplace, verification requirements, and applicable laws and policies. Requirements should be checked for the specific business and target country."
      },
      {
        "q": "Which international Amazon marketplaces can E-COMET support?",
        "a": "The marketplaces will be considered based on current availability, seller eligibility, product suitability, language requirements, and the scope agreed with the business. The available list should be confirmed during consultation rather than assuming every marketplace is suitable."
      },
      {
        "q": "Can E-COMET guarantee Amazon Global account approval?",
        "a": "No. Amazon controls seller verification, eligibility, account approval, and marketplace access. E-COMET can provide guidance and preparation support but cannot guarantee approval."
      },
      {
        "q": "Do I need an existing Amazon India seller account?",
        "a": "Not necessarily in every situation. The appropriate registration route depends on your business circumstances and the destination marketplace's current requirements. This will be reviewed during consultation."
      },
      {
        "q": "Can you help with international product listings?",
        "a": "Yes. Listing support may include titles, bullet points, descriptions, keywords, product attributes, catalogue organisation, and content optimisation for agreed products and marketplaces."
      },
      {
        "q": "Can you manage Amazon international advertising?",
        "a": "We can support eligible advertising activities where the seller account, products, marketplace, and ad formats qualify. Campaign scope and advertising budgets are agreed separately."
      },
      {
        "q": "Do you handle international shipping and customs?",
        "a": "Shipping, fulfilment, customs clearance, import obligations, and physical logistics are not automatically included in marketplace management. We can help coordinate relevant marketplace information, but specialist logistics or customs services may need to be arranged separately."
      },
      {
        "q": "Can you help with international taxes and compliance?",
        "a": "We can help identify relevant marketplace notifications and organise information for review. Tax registration, legal interpretation, customs obligations, and product compliance should be confirmed with appropriately qualified professionals."
      },
      {
        "q": "How much does Amazon Global Management cost?",
        "a": "We do not display fixed prices on our website. The quotation depends on the marketplaces, product catalogue size, listing requirements, advertising scope, operational complexity, and reporting needs. You can request a consultation for a tailored proposal."
      },
      {
        "q": "What is the difference between Orbit, Nova, and Cosmic?",
        "a": "Orbit focuses on launch preparation, Nova focuses on ongoing management for an agreed marketplace scope, and Cosmic is designed for broader multi-marketplace coordination. Exact deliverables and limits are finalised in the proposal."
      },
      {
        "q": "How long does it take to launch internationally?",
        "a": "There is no universal launch timeline. It depends on seller verification, documentation, product eligibility, listing requirements, marketplace approvals, and operational readiness. A more informed estimate can be discussed after reviewing your situation."
      },
      {
        "q": "Can you guarantee international sales or profits?",
        "a": "No. Sales, profits, rankings, and advertising performance depend on factors such as product demand, pricing, competition, customer experience, advertising, fulfilment, and marketplace conditions. Our work focuses on agreed management activities and improvement opportunities."
      },
      {
        "q": "Is E-COMET OUTVERSE officially affiliated with Amazon?",
        "a": "E-COMET OUTVERSE provides independent marketplace management support. Unless explicitly verified and documented, the company should not be presented as an official Amazon partner, representative, or endorsed service provider."
      }
    ],
