    "faqs": [
      {
        "q": "What is WooCommerce Store Management?",
        "a": "It is the ongoing maintenance and administration of a WooCommerce store, including agreed product updates, inventory coordination, order monitoring, website content changes and routine maintenance."
      },
      {
        "q": "Is WooCommerce Store Management different from WooCommerce Website Development?",
        "a": "Yes. Development focuses on building or changing the website. Store management focuses on ongoing operations and maintenance after the store is available."
      },
      {
        "q": "Do I need an existing WooCommerce store?",
        "a": "For ongoing management, an existing store is generally required. If you need a new store, we can discuss website development first."
      },
      {
        "q": "Can you upload and update products?",
        "a": "Yes. Product uploads and updates can be included within agreed limits and based on accurate product information supplied or approved by your business."
      },
      {
        "q": "Can you manage product variations?",
        "a": "Yes. We can assist with supported simple and variable product configurations within the agreed scope. Complex product rules may require additional development."
      },
      {
        "q": "Can you update prices and inventory?",
        "a": "We can update prices and stock records using authorised instructions and reliable information from your business or inventory system."
      },
      {
        "q": "Will you manage my orders?",
        "a": "We can provide the order-monitoring and administrative coordination activities specified in the agreement. Physical fulfilment is not included unless separately contracted."
      },
      {
        "q": "Can you manage WordPress plugins and themes?",
        "a": "We can coordinate agreed updates and perform basic checks. Compatibility issues, custom coding and advanced technical troubleshooting may require separate work."
      },
      {
        "q": "Will you provide website backups?",
        "a": "Backup coordination can be included if agreed. The proposal should define the backup method, frequency, retention and whether restoration testing is included."
      },
      {
        "q": "Can you provide security and malware protection?",
        "a": "We can coordinate agreed routine maintenance and identify visible issues. Advanced security monitoring, malware removal and incident recovery require explicit scope and may need specialist services."
      },
      {
        "q": "Can you improve my store's SEO?",
        "a": "We can maintain agreed on-page SEO elements and recommend improvements. Search rankings and sales cannot be guaranteed."
      },
      {
        "q": "Can you manage payment gateways and shipping settings?",
        "a": "We can assist with supported configuration based on your approved requirements. Provider approval, shipping availability and applicable rules depend on your business and chosen providers."
      },
      {
        "q": "Will you manage my hosting?",
        "a": "Hosting-provider coordination may be included if agreed. Hosting subscriptions, infrastructure administration and advanced server troubleshooting are separate unless specifically included."
      },
      {
        "q": "Are plugins and themes included in the package?",
        "a": "Not automatically. Premium themes, plugin licences, hosting fees and third-party costs are separate unless expressly included in your quotation."
      },
      {
        "q": "How often will you update my store?",
        "a": "The schedule depends on your selected package and requirements. The final scope will define update frequency, task limits and reporting."
      },
      {
        "q": "Can you redesign my WooCommerce website?",
        "a": "Yes, but a major redesign or custom development project may need a separate Website Development quotation."
      },
      {
        "q": "Do you guarantee more sales?",
        "a": "No. Store management can help maintain organised operations, but sales depend on product demand, pricing, traffic, competition, customer experience, fulfilment and other factors."
      },
      {
        "q": "How much does WooCommerce Store Management cost?",
        "a": "Pricing depends on catalogue size, variation complexity, maintenance needs, plugin setup, update frequency and support requirements. E-COMET OUTVERSE provides a custom quotation after consultation."
      },
      {
        "q": "How will you access my website?",
        "a": "Access should be provided through appropriate WordPress user accounts and the minimum permissions needed for the agreed work. Avoid sharing administrator passwords through unsecured channels."
      }
    ],
